import {tex} from './math.mjs';
const b=s=>tex(s,true),p=s=>`<p>${s}</p>`,h=s=>`<h3>${s}</h3>`;
const practice=(title,body)=>`<details class="extension"><summary>Práctica desarrollada · ${title}</summary><div class="detail-body">${body}</div></details>`;
// Referencias explícitas: cada lección corresponde a un apartado real del extracto.
export const chapter3Lessons=[
 {title:'Espacios vectoriales: de las flechas a las funciones',nav:'Espacios vectoriales',pages:'68–70',desc:'Comprueba cierre y linealidad en vectores, polinomios y funciones.'},
 {title:'Dependencia lineal y dimensión',nav:'Dependencia y dimensión',pages:'70–71',desc:'Encuentra relaciones entre vectores y distingue conjunto generador de base.'},
 {title:'Bases y coordenadas: qué cambia y qué permanece',nav:'Bases y coordenadas',pages:'71–75',desc:'Cambia la base sin mover el vector y reconstruye las coordenadas originales.'},
 {title:'Operadores lineales y matrices equivalentes',nav:'Operadores y matrices',pages:'74–77',desc:'Describe el mismo operador en dos bases y verifica la transformación por similitud.'},
 {title:'Representar un grupo mediante matrices',nav:'Representaciones',pages:'77–79',desc:'Comprueba el homomorfismo y distingue dimensión, orden del grupo y fidelidad.'},
 {title:'Representaciones equivalentes y caracteres',nav:'Caracteres',pages:'79–80',desc:'La traza no cambia por similitud y es constante en cada clase de conjugación.'},
 {title:'Construir y sumar representaciones',nav:'Suma directa',pages:'80–86',desc:'Combina espacios invariantes independientes y sigue sus dimensiones y caracteres.'},
 {title:'Simetría del Hamiltoniano y clasificación de estados',nav:'Hamiltoniano',pages:'86–88',desc:'Relaciona conmutación, subespacios de energía y degeneración protegida o accidental.'},
 {title:'Producto escalar, métrica y ortonormalización',nav:'Métrica y unitariedad',pages:'88–91',desc:'Una base oblicua necesita una matriz de Gram para medir longitudes y ángulos.'},
 {title:'Adjunto, autoadjunto y unitario',nav:'Operador adjunto',pages:'91–92',desc:'Calcula el adjunto correcto en una base que no es ortonormal.'},
 {title:'Unitarizar una representación de un grupo finito',nav:'Unitarización',pages:'92–93',desc:'Promedia una métrica positiva sobre el grupo y cambia de base para conservar la norma.'},
 {title:'Completitud y espacio de Hilbert',nav:'Espacio de Hilbert',pages:'93–94',desc:'Una sucesión de Cauchy puede necesitar un espacio mayor para contener su límite.'},
 {title:'Reducibilidad y descomposición en irreducibles',nav:'Reducibilidad',pages:'94–98',desc:'Separa la representación de permutación del triángulo en un singlete y un doblete.'},
 {title:'Lemas de Schur e intertwiners',nav:'Lemas de Schur',pages:'98–101',desc:'El conmutante distingue bloques irreducibles sobre los complejos.'},
 {title:'Ortogonalidad de elementos de matriz y caracteres',nav:'Ortogonalidad',pages:'101–104',desc:'Comprueba las sumas sobre todo el grupo y el peso de cada clase.'},
 {title:'Multiplicidades y criterio de irreducibilidad',nav:'Analizar caracteres',pages:'104–106',desc:'Descompón un carácter usando productos escalares ponderados por tamaños de clase.'},
 {title:'Representación regular y álgebra del grupo',nav:'Regular y álgebra',pages:'106–111',desc:'La representación regular contiene cada irreducible tantas veces como su dimensión.'},
 {title:'Proyectores y funciones adaptadas a la simetría',nav:'Proyectores',pages:'111–113',desc:'Extrae componentes de simetría y distingue proyectores de fila e isotípicos.'},
 {title:'Representaciones de productos directos',nav:'Productos directos',pages:'114',desc:'Construye el producto tensorial y multiplica los caracteres de los factores.'}
].map((v,i)=>({...v,reference:'3-'+(i+1)}));
export const chapter3Notes=[
 h('Un espacio no necesita tener flechas')+p('Un espacio vectorial combina dos operaciones: suma de objetos y multiplicación por escalares. Hamermesh trabaja principalmente con escalares complejos. Los axiomas garantizan cierre, asociatividad y distributividad, un vector cero y un inverso aditivo. La suma es abeliana; la multiplicación por escalares añade estructura que un grupo aditivo por sí solo no contiene.')+b(String.raw`\alpha(x+y)=\alpha x+\alpha y,\qquad (\alpha+\beta)x=\alpha x+\beta x.`)+h('Funciones como vectores')+p('Los polinomios de grado a lo sumo dos forman un espacio de dimensión tres. Sumar dos polinomios cuadráticos puede cancelar el término de mayor grado, pero el resultado sigue perteneciendo al espacio. Por eso conviene escribir «grado a lo sumo dos»: los polinomios de grado exactamente dos no forman un subespacio, pues no contienen el cero.')+b(String.raw`P_2=\{a_0+a_1t+a_2t^2:a_j\in\mathbb C\}.`)+p('El laboratorio representa un polinomio por su vector de coeficientes y calcula una combinación lineal. Los coeficientes de los controles son reales para poder dibujar una curva, pero el espacio teórico puede ser complejo. Ningún eje del gráfico añade una dimensión al espacio de polinomios: las dimensiones cuentan coeficientes independientes.')+practice('Comprobar un subespacio',p('Las funciones que se anulan en t=0 forman un subespacio de P₂: tienen coeficiente constante nulo. Su base puede ser {t,t²}. En cambio las funciones con valor uno en t=0 forman un conjunto afín: la suma de dos tiene valor dos y no permanece en el conjunto.')),
 h('La relación homogénea es la prueba')+b(String.raw`\alpha_1v_1+\cdots+\alpha_nv_n=0.`)+p('Los vectores son linealmente independientes si la única solución es que todos los coeficientes se anulen. Si existe una solución no trivial, uno de los vectores puede expresarse usando los demás. La dimensión es el número de elementos de una base, no el número de vectores que hayas escrito.')+h('Una familia que pierde dimensión')+b(String.raw`v_1=(1,0),\quad v_2=(a,b),\qquad\det[v_1\ v_2]=b.`)+p('Si b no es cero, los dos vectores forman una base del plano. Si b es cero, ambos están sobre una misma recta. Cerca de b=0 el sistema sigue siendo invertible matemáticamente, pero las coordenadas pueden crecer mucho: independencia exacta y estabilidad numérica son conceptos diferentes.')+practice('Un conjunto generador redundante',p('Los vectores (1,0), (0,1), (1,1) generan el plano, pero no son una base. La relación v₃−v₁−v₂=0 demuestra la dependencia. Un algoritmo de rango puede escoger dos columnas pivote y descartar la tercera sin cambiar el espacio generado.'))+h('Dimensión finita e infinita')+p('En P₂, {1,t,t²} es una base. Para todos los polinomios necesitas {1,t,t²,…}, pero cada polinomio es una combinación finita. Las expansiones infinitas de funciones requieren además un sentido de convergencia: no se justifican solo por los axiomas algebraicos de un espacio vectorial.'),
 h('El vector y su lista de coordenadas son distintos')+p('Fija una base de columnas B. Un vector físico v y su columna de coordenadas c se relacionan mediante v=Bc. Al escoger otra base cambia c, aunque el vector siga siendo el mismo.')+b(String.raw`v=Bc,\qquad c=B^{-1}v.`)+p('En esta guía usamos columnas para las bases. Si la base nueva es B′=BS, las coordenadas cumplen c′=S⁻¹c. Esta convención evita confundir un cambio pasivo de coordenadas con un movimiento activo del vector. El libro organiza algunos índices y vectores de base de otra manera; las expresiones deben compararse junto a su convención.')+h('Una base oblicua')+b(String.raw`B=\begin{pmatrix}1&s\\0&1\end{pmatrix},\qquad v=(x,y)^{\mathsf T},\qquad c=(x-sy,y)^{\mathsf T}.`)+p('El laboratorio mantiene v y varía la inclinación s de la segunda columna. El vector no se mueve, pero cambian sus componentes. La norma de la columna de coordenadas no tiene por qué coincidir con la longitud del vector si B no es ortonormal.')+practice('Reconstruir antes de interpretar',p('Con s=1 y v=(2,1), las coordenadas son c=(1,1). Multiplicar Bc recupera (2,1). Si trataras c como coordenadas cartesianas del dibujo, representarías otro vector. La métrica correcta para las coordenadas oblicuas será BᵀB.'))+p('La inversa solo existe para una base independiente. Una familia redundante necesita otras herramientas y no determina coordenadas únicas.'),
 h('Un operador, varias matrices')+p('Un operador T es lineal si conserva las combinaciones lineales. Una vez fijada una base, su matriz A contiene como columnas las coordenadas de las imágenes de los vectores básicos.')+b(String.raw`T(\alpha x+\beta y)=\alpha T(x)+\beta T(y),\qquad [Tv]_B=A[v]_B.`)+h('Derivar la similitud')+p('Si las coordenadas antiguas y nuevas cumplen c=Sc′, la imagen tiene coordenadas antiguas Ac=ASc′. Para escribirla en la base nueva debes multiplicar por S⁻¹:')+b(String.raw`A'=S^{-1}AS.`)+p('La misma matriz S debe aplicarse a todas las matrices de una representación. Diagonalizar cada elemento con una base distinta no constituye una equivalencia global. La similitud conserva traza, determinante y polinomio característico, pero no conserva necesariamente las normas euclídeas de las columnas.')+practice('Operador diagonal en una base oblicua',p('T multiplica la primera componente cartesiana por 2 y la segunda por 1. En una base con B=[[1,s],[0,1]], su matriz es [[2,s],[0,1]]. Aunque aparezca un término fuera de la diagonal, sigue teniendo autovalores 2 y 1.'))+h('Equivalencia de operadores y de representaciones')+p('El laboratorio calcula A y S⁻¹AS y verifica que ambos producen la misma imagen del vector al reconstruirla en la base cartesiana. La igualdad de autovalores de una sola matriz no basta para identificar dos representaciones completas de un grupo.'),
 h('Un homomorfismo hacia operadores invertibles')+b(String.raw`D:G\longrightarrow GL(V),\qquad D(gh)=D(g)D(h),\quad D(e)=I,\quad D(g^{-1})=D(g)^{-1}.`)+p('La dimensión de la representación es la dimensión de V. El orden del grupo es su número de elementos. Un grupo de seis elementos puede tener representaciones de dimensión uno, dos, tres o seis. No confundas esas cantidades.')+h('Un mismo grupo con varias realizaciones')+p('El laboratorio usa D₃, las seis simetrías del triángulo, con r³=s²=e y sr=r⁻¹s. Puedes elegir la representación trivial A₁, la representación de signo A₂, la representación plana E, la permutación de tres vértices y la regular de dimensión seis. Todas satisfacen la ley de grupo.')+b(String.raw`D(rs)=D(r)D(s)\quad\text{(se aplica primero }s\text{)}.`)+practice('Comprobar fidelidad',p('La representación trivial envía todos los elementos a 1: su núcleo es todo el grupo. La de signo envía las rotaciones a 1 y las reflexiones a −1: su núcleo contiene tres elementos. La plana, la de vértices y la regular distinguen los seis elementos y son fieles.'))+p('Una representación no fiel sigue siendo una representación válida. Factoriza a través del cociente por su núcleo. Los controles comparan el producto de matrices con la matriz del producto, sin inferir fidelidad a partir del tamaño de una matriz.'),
 h('El carácter comprime la información matricial')+b(String.raw`\chi_D(g)=\operatorname{tr}D(g).`)+p('La traza es invariante bajo similitud porque tr(AB)=tr(BA). Si D′(g)=S⁻¹D(g)S para una misma S invertible y todo g, ambos caracteres coinciden. Además, dos elementos conjugados tienen matrices semejantes dentro de cualquier representación, de modo que el carácter es constante en una clase.')+b(String.raw`\chi(hgh^{-1})=\operatorname{tr}\bigl(D(h)D(g)D(h)^{-1}\bigr)=\chi(g).`)+h('Tres clases en D₃')+p('Las clases son la identidad, los dos giros no triviales y las tres reflexiones. Sus tamaños son 1, 2 y 3. Para las irreducibles complejas A₁, A₂ y E los caracteres sobre esas clases son:')+b(String.raw`\chi_{A_1}=(1,1,1),\quad\chi_{A_2}=(1,1,-1),\quad\chi_E=(2,-1,0).`)+practice('Leer una rotación plana',p('En E, un giro de 120° tiene traza 2cos(120°)=−1. Una reflexión plana tiene autovalores +1 y −1 y traza cero. La identidad tiene traza 2, que revela la dimensión.'))+p('Para representaciones complejas finito-dimensionales de un grupo finito, el carácter completo determina la clase de equivalencia. Esa conclusión usa la reducción completa y la ortogonalidad posteriores; no se deduce simplemente de conocer la traza de una sola matriz.'),
 h('Suma directa de espacios y operadores')+p('Si V y W son espacios de representación, en V⊕W un vector es un par (v,w). El grupo actúa por separado en cada componente:')+b(String.raw`(D\oplus E)(g)=\begin{pmatrix}D(g)&0\\0&E(g)\end{pmatrix}.`)+p('La dimensión y el carácter se suman. Esto no es sumar dos matrices del mismo tamaño: D(g)+E(g) no suele satisfacer la ley de grupo. La suma directa conserva dos espacios independientes en bloques.')+b(String.raw`\dim(D\oplus E)=\dim D+\dim E,\qquad\chi_{D\oplus E}=\chi_D+\chi_E.`)+h('Construir desde funciones')+p('El libro obtiene representaciones transformando funciones y reuniendo un espacio cerrado bajo la acción del grupo. La acción sobre funciones se escribe O_g f(x)=f(g⁻¹x), de modo que O_gO_h=O_gh. El inverso en el argumento es esencial para conservar el orden de la composición.')+practice('Dos copias de un doblete',p('A₁⊕E⊕E tiene dimensión 1+2+2=5 y carácter (5,−1,1). No es una nueva irreducible de dimensión cinco: contiene una copia trivial y dos copias equivalentes del doblete. El laboratorio permite cambiar las multiplicidades y construye la matriz por bloques.'))+p('Escoger nuevas combinaciones de funciones básicas puede ocultar o revelar los bloques, pero no cambia qué subrepresentaciones contiene el espacio. La sección de reducibilidad abordará cómo recuperarlos.'),
 h('Por qué la simetría clasifica los estados')+p('Si el Hamiltoniano H conmuta con todas las transformaciones O_g, cada subespacio propio de energía es invariante. En efecto:')+b(String.raw`H\psi=E\psi,\quad [H,O_g]=0\quad\Longrightarrow\quad H(O_g\psi)=E(O_g\psi).`)+p('Las funciones de un nivel degenerado forman una representación del grupo. Si esa representación es reducible, el nivel puede dividirse en sectores de simetría distintos. Por tanto, «nivel degenerado» e «irreducible» no son sinónimos.')+h('Un modelo de tres estados')+p('Para la representación de permutación del triángulo, el vector uniforme es un singlete A₁ y el plano de componentes de suma cero es un doblete E. Un Hamiltoniano real simétrico que conmuta con todas las permutaciones tiene la forma:')+b(String.raw`H=aI+bJ,\qquad J_{ij}=1,\qquad E_{A_1}=a+3b,\quad E_E=a.`)+p('El doblete tiene degeneración dos protegida por la simetría en este modelo. Si b=0, singlete y doblete coinciden en energía: la degeneración total tres es accidental respecto a D₃, pues une dos irreducibles diferentes.')+practice('Romper la simetría de forma controlada',p('El laboratorio añade en la base adaptada una perturbación diagonal con entradas (0,δ,−δ). Separa el doblete en energías a+δ y a−δ. El conmutador con el giro deja de anularse si δ≠0. El modelo es algebraico: no identifica esos parámetros con una molécula concreta.')),
 h('La métrica convierte coordenadas en geometría')+p('En un espacio complejo el producto escalar es antilineal en el primer argumento y lineal en el segundo, como en Hamermesh. En una base cualquiera se representa mediante una matriz hermítica positiva definida M:')+b(String.raw`\langle x,y\rangle=x^\dagger My,\qquad M^\dagger=M,\qquad x^\dagger Mx>0\ (x\ne0).`)+p('«No negativo» no basta para definir un producto escalar: un vector no nulo no puede tener norma cero. En una base ortonormal M=I. En una base de columnas B dentro de un espacio euclídeo, M=BᵀB; en el caso complejo se usa B†B.')+h('Gram–Schmidt')+b(String.raw`u_1=\frac{v_1}{\|v_1\|},\qquad w_2=v_2-u_1\langle u_1,v_2\rangle,\qquad u_2=\frac{w_2}{\|w_2\|}.`)+p('El segundo paso exige que los vectores iniciales sean independientes. Si el residuo es cero no has obtenido una base de dimensión dos. El laboratorio usa una base real oblicua, muestra su Gram y comprueba que la base ortonormal resultante tiene Gram identidad.')+practice('La misma longitud con coordenadas distintas',p('Si v=Bc, entonces vᵀv=cᵀBᵀBc. Las coordenadas pueden cambiar su norma euclídea mientras la longitud física siga siendo la misma al emplear M. Esa distinción será decisiva al hablar de matrices unitarias en bases no ortonormales.'))+p('Para matrices cuadradas, U†U=I equivale a que las columnas sean ortonormales y a U⁻¹=U†. En el caso real se habla de matrices ortogonales.'),
 h('El adjunto depende del producto escalar')+b(String.raw`\langle Ax,y\rangle=\langle x,A^{\sharp}y\rangle.`)+p('El símbolo ♯ distingue aquí el adjunto del operador, expresado en coordenadas, del conjugado transpuesto de una matriz. En una base con métrica M, la definición exige:')+b(String.raw`x^\dagger A^\dagger My=x^\dagger MA^{\sharp}y\quad\Longrightarrow\quad A^{\sharp}=M^{-1}A^\dagger M.`)+p('Solo si M=I coincide automáticamente con A†. Un operador autoadjunto puede tener una matriz que no sea hermítica en una base oblicua. La condición correcta es A†M=MA. Un operador unitario cumple A†MA=M.')+h('Ejemplo calculado')+p('T es diagonal con valores reales 2 y 1 en una base cartesiana. Tras un cambio oblicuo S aparece A=S⁻¹diag(2,1)S. El laboratorio calcula M=SᵀS y verifica que A♯=A, aunque Aᵀ y A difieran si la base no es ortogonal.')+practice('No confundir dos propiedades',p('Una rotación real no trivial es unitaria, pero normalmente no es autoadjunta. Una matriz diagonal real con entradas 2 y 1 es autoadjunta, pero no unitaria. La primera conserva normas; la segunda representa un observable con autovalores reales.'))+p('En dimensión infinita, la definición del adjunto requiere además precisar dominios de operadores. El ejemplo de matrices finitas evita esas dificultades y no extiende sin hipótesis todas sus equivalencias a operadores no acotados.'),
 h('Promediar un producto escalar')+p('Para una representación compleja de un grupo finito, parte de cualquier producto escalar positivo. La media de sus imágenes por el grupo define otro producto positivo e invariante:')+b(String.raw`M=\frac1{|G|}\sum_{g\in G}D(g)^\dagger D(g),\qquad D(h)^\dagger MD(h)=M.`)+p('La positividad es estricta porque cada D(g) es invertible. La invariancia se demuestra reindexando gh: al recorrer g todo el grupo, gh también lo recorre. No depende de adivinar una base conveniente.')+h('Convertir la métrica en identidad')+p('Factoriza M=C†C, por ejemplo mediante Cholesky. Entonces la representación transformada por C es unitaria respecto al producto escalar usual:')+b(String.raw`U(g)=CD(g)C^{-1},\qquad U(g)^\dagger U(g)=I.`)+practice('Una representación que parece no conservar longitudes',p('El laboratorio parte de E(g), las simetrías planas ortogonales de D₃, y las deforma con una base oblicua S. Las nuevas matrices S⁻¹E(g)S ya no conservan la norma euclídea ordinaria. La media M recupera una norma que sí conservan; aplicar C recupera matrices ortogonales.'))+h('Hipótesis que importan')+p('La prueba utiliza la suma finita y un cuerpo de característica cero. Para grupos compactos existe una versión con medida de Haar normalizada. Para grupos infinitos no compactos no se puede reemplazar esa suma por una «media» sin justificar su existencia y sus propiedades. La guía no afirma unitarizabilidad universal.'),
 h('Cauchy y convergencia no son la misma afirmación')+p('Una sucesión es de Cauchy si sus términos se aproximan entre sí. Un espacio es completo si toda sucesión de Cauchy tiene un límite dentro del mismo espacio. Un espacio con producto escalar que es completo en la norma asociada es un espacio de Hilbert.')+b(String.raw`\forall\varepsilon>0\ \exists N:\ m,n>N\Rightarrow\|x_m-x_n\|<\varepsilon.`)+h('Una sucesión de soporte finito')+p('En el espacio de secuencias con solo un número finito de componentes no nulas, considera x_N=(1,q,q²,…,qⁿ⁻¹,0,…), con 0<q<1. Cada término pertenece al espacio de soporte finito, pero la secuencia límite (1,q,q²,…) no tiene soporte finito.')+b(String.raw`\|x_\infty-x_N\|_2=\frac{q^N}{\sqrt{1-q^2}},\qquad\|x_N\|_2^2=\frac{1-q^{2N}}{1-q^2}.`)+p('La fórmula de la cola prueba convergencia en ℓ² y la propiedad de Cauchy del truncamiento. También muestra que el espacio de soporte finito no es completo con esa norma. Su completación es ℓ². Para q=0 el límite sí tiene soporte finito; para q≥1 esta construcción deja de pertenecer a ℓ².')+practice('Cuántos términos hacen falta',p('Para conseguir error menor que ε exige qᴺ<ε√(1−q²). Como log q es negativo, al dividir por él se invierte la desigualdad. El laboratorio muestra la cola exacta: una curva decreciente no demuestra por sí sola completitud de un espacio.'))+p('Todo espacio de dimensión finita con producto escalar es completo. Los problemas de dominio y continuidad aparecen al pasar a dimensión infinita.'),
 h('Un subespacio invariante común')+p('Una representación es reducible si existe un subespacio distinto de cero y del espacio total que se conserva bajo todos los elementos del grupo. Encontrar un autovector de una matriz no basta: el mismo subespacio debe servir para la representación completa.')+b(String.raw`D(g)W\subset W\quad\text{para todo }g\in G.`)+h('Triángulo: del espacio de vértices al singlete y doblete')+p('En la representación de permutación sobre tres coordenadas, el vector (1,1,1) genera una recta invariante. Su complemento ortogonal, las coordenadas de suma cero, también es invariante porque las matrices son unitarias. Elige las columnas ortonormales:')+b(String.raw`Q=\left[\frac{(1,1,1)^{\mathsf T}}{\sqrt3},\ \frac{(2,-1,-1)^{\mathsf T}}{\sqrt6},\ \frac{(0,1,-1)^{\mathsf T}}{\sqrt2}\right].`)+b(String.raw`Q^\dagger P(g)Q=1\oplus E'(g),\qquad P\simeq A_1\oplus E.`)+practice('Comprobar con generadores',p('Basta comprobar la invariancia para r y s, pues generan D₃. En la nueva base todos los bloques que conectan el singlete y el doblete se anulan. El carácter de permutación es (3,0,1)=(1,1,1)+(2,−1,0).'))+h('Reducible frente a completamente reducible')+p('Un subespacio invariante puede dar una forma triangular sin que exista un complemento invariante. Para representaciones unitarias el complemento ortogonal sí es invariante. Por unitarización, toda representación compleja finito-dimensional de un grupo finito se descompone completamente.'),
 h('Un operador que entrelaza dos acciones')+b(String.raw`D(g)A=AE(g)\quad\text{para todo }g.`)+p('Si D y E son irreducibles, el núcleo y la imagen de A son invariantes. Por irreducibilidad, A es cero o es un isomorfismo; en este último caso las representaciones son equivalentes. Si actúan en dimensiones distintas no puede haber un isomorfismo.')+h('El conmutante de una irreducible compleja')+p('Si A conmuta con todas las matrices de una irreducible sobre los complejos, A es un múltiplo de la identidad. Escoge un autovalor λ de A: el núcleo de A−λI es no nulo e invariante, así que debe ser todo el espacio.')+b(String.raw`[A,D(g)]=0\ \forall g,\quad D\text{ irreducible sobre }\mathbb C\quad\Rightarrow\quad A=\lambda I.`)+practice('Construir un conmutante mediante promedio',b(String.raw`\mathcal T(X)=\frac1{|G|}\sum_gD(g)XD(g)^{-1}.`)+p('Para el doblete E de D₃, el resultado es tr(X)I/2. El laboratorio compara el promedio calculado con ese valor y muestra el conmutador con r y s. El promedio de una matriz no es la afirmación de que toda matriz inicial conmute.'))+h('El cuerpo no es un detalle')+p('Sobre los reales el conmutante de una irreducible puede ser mayor que los escalares. Por ejemplo, el giro de 120° en el plano real conmuta con el giro de 90°; la representación real de C₃ es irreducible, pero sobre los complejos se separa en dos rectas propias. Las conclusiones de esta guía sobre caracteres e irreducibilidad se formulan sobre ℂ.'),
 h('Elementos de matriz como funciones sobre G')+p('En una irreducible unitaria, cada posición matricial define una función g↦Dᵅᵢⱼ(g). El gran teorema de ortogonalidad establece:')+b(String.raw`\frac1{|G|}\sum_{g\in G}D^{(\alpha)}_{ij}(g)^*D^{(\beta)}_{kl}(g)=\frac{\delta_{\alpha\beta}\delta_{ik}\delta_{jl}}{d_\alpha}.`)+p('Los elementos de matriz de irreducibles inequivalentes son ortogonales; dentro de una irreducible las funciones de posiciones distintas también lo son. No se suma solo sobre los generadores: hay que recorrer todos los elementos del grupo.')+h('Caracteres: comprimir la suma por clases')+b(String.raw`\langle\chi_\alpha,\chi_\beta\rangle=\frac1{|G|}\sum_C|C|\chi_\alpha(C)^*\chi_\beta(C)=\delta_{\alpha\beta}.`)+p('La suma sobre clases necesita sus tamaños. En D₃ las ponderaciones son 1,2,3 y el denominador es 6. Una media sin ponderación de las tres columnas de la tabla no representa el producto escalar del grupo.')+practice('Norma del doblete',b(String.raw`\langle\chi_E,\chi_E\rangle=\frac{1\cdot2^2+2\cdot(-1)^2+3\cdot0^2}{6}=1.`)+p('El laboratorio permite escoger dos entradas matriciales del doblete y calcula su producto escalar sobre las seis operaciones. Para posiciones iguales el resultado es 1/2 y para distintas es cero.'))+p('Las matrices del ejemplo son reales, por eso la conjugación compleja no cambia sus entradas. La fórmula general sí necesita el conjugado; omitirlo falla para caracteres complejos de grupos cíclicos.'),
 h('Encontrar cuántas copias contiene una representación')+p('La reducción completa permite escribir D como suma directa de irreducibles con multiplicidades enteras no negativas. Sus caracteres se suman:')+b(String.raw`\chi_D=\sum_\alpha m_\alpha\chi_\alpha,\qquad m_\alpha=\langle\chi_\alpha,\chi_D\rangle.`)+h('Norma del carácter e irreducibilidad')+b(String.raw`\langle\chi_D,\chi_D\rangle=\sum_\alpha m_\alpha^2.`)+p('Para una representación compleja no nula de un grupo finito, la norma es uno exactamente cuando es irreducible. Si vale dos, hay dos irreducibles inequivalentes, cada una una vez. Si vale cuatro, puede haber cuatro irreducibles distintas o dos copias de una misma irreducible: la norma sola no distingue esos casos.')+practice('Descomponer la permutación de vértices',p('Su carácter sobre las clases es (3,0,1). Los productos escalares con A₁, A₂ y E dan (1,0,1). La dimensión reconstruida es 1+2=3 y la norma del carácter es 2. La traza de identidad verifica la dimensión, pero no sustituye a las demás clases.'))+h('No toda fila de números es un carácter')+p('El laboratorio ofrece caracteres reales procedentes de representaciones conocidas: trivial, signo, doblete, permutación, regular y E⊗E. En el último caso el carácter es (4,1,0) y la reducción A₁⊕A₂⊕E. Si se introdujeran números arbitrarios, multiplicidades fraccionarias o negativas advertirían que no describen una representación ordinaria con la tabla escogida.'),
 h('La representación regular prueba que no faltan irreducibles')+p('El grupo actúa sobre un espacio con una base etiquetada por sus propios elementos. La multiplicación izquierda transforma el vector e_h en e_gh. La identidad fija todos los elementos; cualquier otro g no fija ninguno, por cancelación.')+b(String.raw`\chi_{\rm reg}(g)=\begin{cases}|G|&g=e,\\0&g\ne e.\end{cases}`)+p('La fórmula de multiplicidades da mᵅ=dᵅ. Al comparar dimensiones se obtiene la igualdad fundamental:')+b(String.raw`\mathbb C[G]\simeq\bigoplus_\alpha d_\alpha V_\alpha,\qquad\sum_\alpha d_\alpha^2=|G|.`)+h('Clases y centro del álgebra')+p('El álgebra de grupo permite combinaciones lineales formales de elementos y extiende la multiplicación bilinealmente. Las sumas de clases pertenecen al centro. Sus productos se expresan como combinaciones enteras de sumas de clases; el coeficiente de una clase cuenta cuántas veces aparece cada uno de sus elementos, no el total de pares de esa clase.')+b(String.raw`K_i=\sum_{g\in C_i}g,\qquad K_iK_j=\sum_kc_{ij}^{\ k}K_k.`)+practice('Producto de las reflexiones de D₃',p('Hay nueve pares de reflexiones. Tres producen la identidad y seis producen giros, tres por cada giro. Por ello K_s²=3K_e+3K_r, no 3K_e+6K_r. El laboratorio enumera los pares para comprobarlo.'))+p('Sobre ℂ el número de irreducibles inequivalentes coincide con el número de clases. Para D₃: 1²+1²+2²=6, tres irreducibles y tres clases. La regular es A₁⊕A₂⊕2E.'),
 h('Proyectar sin adivinar la base adaptada')+p('En una representación unitaria, el carácter de una irreducible permite construir el proyector sobre todo su sector isotípico, es decir, sobre todas las copias de ese tipo:')+b(String.raw`P_\alpha=\frac{d_\alpha}{|G|}\sum_g\chi_\alpha(g)^*D(g).`)+p('Los proyectores satisfacen Pᵅ²=Pᵅ, PᵅPᵝ=0 para tipos distintos y su suma es la identidad en el espacio considerado. Su rango es mᵅdᵅ, no necesariamente dᵅ. Aplicar un proyector a un vector puede dar cero: el vector inicial puede no contener ese tipo.')+h('Un triángulo, tres componentes')+p('En la representación de vértices de D₃, P_A₁ es J/3, P_E=I−J/3 y P_A₂=0. Al proyectar (x,y,z), el singlete contiene el valor medio repetido y el doblete contiene las desviaciones respecto a la media.')+practice('Proyectar (1,2,3)',p('La media es 2. La componente A₁ es (2,2,2) y la componente E es (−1,0,1); se suman para recuperar el original y son ortogonales. El signo no aparece en este espacio, aunque sea una irreducible válida del grupo.'))+h('Filas y operadores de transferencia')+b(String.raw`P^{(\alpha)}_{ij}=\frac{d_\alpha}{|G|}\sum_gD^{(\alpha)}_{ij}(g)^*D(g).`)+p('Los operadores diagonales seleccionan filas y los no diagonales relacionan compañeros dentro de cada copia. El proyector de carácter es la suma de los diagonales. Un proyector central no separa entre sí varias copias equivalentes: para eso se necesita información adicional.'),
 h('Del par de grupos al producto tensorial')+p('Para grupos finitos G y H, si D y E son irreducibles complejas de los factores, la representación del producto directo se construye sobre V⊗W:')+b(String.raw`(D\boxtimes E)(g,h)=D(g)\otimes E(h).`)+p('La dimensión se multiplica y también lo hacen los caracteres. Todas las irreducibles complejas del producto directo de grupos finitos se obtienen de esta forma, a partir de pares de irreducibles de sus factores.')+b(String.raw`d_{D\boxtimes E}=d_Dd_E,\qquad\chi_{D\boxtimes E}(g,h)=\chi_D(g)\chi_E(h).`)+h('Ejemplo: D₃ × C₂')+p('El segundo factor tiene dos caracteres unidimensionales, + y −. Cada irreducible de D₃ produce dos tipos: A₁⁺, A₁⁻, A₂⁺, A₂⁻, E⁺ y E⁻. Sus dimensiones son 1,1,1,1,2,2 y la suma de cuadrados es 12, el orden del producto.')+practice('Multiplicar por un signo',p('En E⁻, el elemento no trivial de C₂ multiplica toda la matriz E(g) por −1. No añade una segunda dimensión al doblete. En cambio, E⊗E para dos factores D₃ tiene dimensión cuatro. El laboratorio deja escoger ambas situaciones.'))+h('Una distinción decisiva')+p('La representación E⊠E del grupo D₃×D₃ es irreducible. Si la restringes al subgrupo diagonal {(g,g)}, su carácter pasa a ser χ_E(g)² y se descompone como A₁⊕A₂⊕E. El producto tensorial de dos representaciones de un mismo grupo no es automáticamente irreducible. No confundas producto directo de grupos con restricción diagonal.')
];
const q=(q,a,correct,why)=>({q,a,correct,why});
